public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    // Base case: if the input array has only one element,
    // return a list containing only one list with that element
    if (nums.length == 1) {
        permutations.add(Arrays.asList(nums[0]));
        return permutations;
    }

    // Recursive case: for each element in the input array,
    // generate all permutations of the remaining elements
    // and add the current element to each permutation
    for (int i = 0; i < nums.length; i++) {
        int current = nums[i];
        int[] remaining = Arrays.copyOfRange(nums, i + 1, nums.length);
        List<List<Integer>> permutationsOfRemaining = permute(remaining);
        for (List<Integer> permutation : permutationsOfRemaining) {
            permutation.add(0, current);
        }
        permutations.addAll(permutationsOfRemaining);
    }

    return permutations;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    boolean[] used = new boolean[nums.length];
    Arrays.fill(used, false);
    permute(result, new ArrayList<Integer>(), nums, used);
    return result;
}

private void permute(List<List<Integer>> result, List<Integer> cur, int[] nums, boolean[] used) {
    if (cur.size() == nums.length) {
        result.add(new ArrayList<>(cur));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            cur.add(nums[i]);
            permute(result, cur, nums, used);
            cur.remove(cur.size() - 1);
            used[i] = false;
        }
    }
}

