public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending coordinates are valid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Initialize a visited matrix to keep track of visited n-tersections
    boolean[][] visited = new boolean[n][n];

    // Queue to store the n-tersections to be visited
    Queue<int[]> queue = new LinkedList<int[]>();

    // Mark the starting n-tersection as visited
    visited[start[0]][start[1]] = true;

    // Add the starting n-tersection to the queue
    queue.add(start);

    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Get the paths from the current n-tersection to its adjacent n-tersections
        int[][] adjacents = getAdjacentNtersections(paths, current[0], current[1]);

        // Iterate through the adjacent n-tersections
        for (int[] adj : adjacents) {
            // Check if the adjacent n-tersection has not been visited
            if (!visited[adj[0]][adj[1]]) {
                // Mark the adjacent n-tersection as visited
                visited[adj[0]][adj[1]] = true;

                // Add the adjacent n-tersection to the queue
                queue.add(adj);
            }
        }
    }

    // If we reach here, it means that the ending n-tersection cannot be reached from the starting n-tersection
    return "cannot be travelled";
}

private static int[][] getAdjacentNtersections(int[][] paths, int x, int y) {
    // Get the paths from the current n-tersection to its adjacent n-tersections
    int[][] adjacents = new int[4][2];
    adjacents[0] = new int[] { x - 1, y };
    adjacents[1] = new int[] { x, y - 1 };
    adjacents[2] = new int[] { x + 1, y };
    adjacents[3] = new int[] { x, y + 1 };

    return adjacents;
}

