private static boolean traverse(int[] current, int[] end, int[][] paths, boolean[] visited) {
    if (current[0] == end[0] && current[1] == end[1]) {
        return true;
    }
    for (int[] path : paths) {
        int row = current[0] + path[0];
        int col = current[1] + path[1];
        if (row >= 0 && row < n && col >= 0 && col < n && path[2] != 0 && !visited[row * n + col]) {
            visited[row * n + col] = true;
            boolean result = traverse(new int[]{row, col}, end, paths, visited);
            if (result) {
                return true;
            }
        }
    }
    return false;
}

