        adjacentN[1] = new int[]{currentX + 1, currentY};
        adjacentN[2] = new int[]{currentX, currentY - 1};
        adjacentN[3] = new int[]{currentX, currentY + 1};

        // loop through the adjacent n-tersections and add them to the queue if they are not visited already
        for (int i = 0; i < adjacentN.length; i++) {
