public static double trimMean(int[] arr) {
    Arrays.sort(arr);
    int n = arr.length;
    int left = round(n * 0.05);
    int right = n - left;
    double sum = 0;
    for (int i = left; i < right; i++) {
        sum += arr[i];
    }
    return sum / (right - left);
}

public double trimMean(int[] arr) {
    int size = arr.length;
    int trimmedSize = (int) Math.floor(size * 0.05);
    int[] trimmedArr = new int[size - 2 * trimmedSize];
    System.arraycopy(arr, trimmedSize, trimmedArr, 0, trimmedSize);
    System.arraycopy(arr, size - trimmedSize, trimmedArr, 2 * trimmedSize, trimmedSize);
    double sum = 0;
    for (int i = 0; i < trimmedArr.length; i++) {
        sum += trimmedArr[i];
    }
    return sum / trimmedArr.length;
}

public static double trimMean(int[] arr) {
    // Step 1: Get the size of the array
    int n = arr.length;

    // Step 2: Get the indices of the 5% smallest and largest elements
    int start = (int) Math.ceil(0.05 * n);
    int end = (int) Math.floor(n - Math.ceil(0.05 * n));

    // Step 3: Sort the array
    Arrays.sort(arr);

    // Step 4: Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = start; i <= end; i++) {
        sum += arr[i];
    }

    // Step 5: Calculate the mean
    double mean = (double) sum / (end - start + 1);

    return mean;
}

public double trimMean(int[] arr) {
    // Calculate the length of the array
    int n = arr.length;

    // Calculate the smallest 5% and largest 5% of the elements
    int smallestIndex = n / 100;
    int largestIndex = n - smallestIndex - 1;

    // Create two temporary arrays to store the elements after removing the smallest and largest elements
    int[] smallestArr = new int[n - smallestIndex];
    int[] largestArr = new int[n - largestIndex];

    // Copy the elements from the original array to the temporary arrays, skipping the smallest and largest elements
    for (int i = 0, k = 0, j = 0; i < n; ++i) {
        if (i < smallestIndex || i > largestIndex) {
            smallestArr[k++] = arr[i];
        } else {
            largestArr[j++] = arr[i];
        }
    }

    // Calculate the mean of the remaining elements in the two temporary arrays
    double smallestMean = sum(smallestArr) / (n - smallestIndex);
    double largestMean = sum(largestArr) / (n - largestIndex);

    // Return the mean of the two means with an error within 10^-5
    return (smallestMean + largestMean) / 2;
}

