        sum += i;
    }
    return (double) sum / arr.length;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1 || k == 0) {
        return false;
    }

    HashMap<Integer, Integer> count = new HashMap<>();
    for (int i = 0; i < n; i++) {
        int value = arr[i];
        if (count.containsKey(value)) {
            count.put(value, count.get(value) + 1);
        } else {
            count.put(value, 1);
        }
    }

    for (int i = 0; i < n / 2; i++) {
        int value1 = arr[i];
        int value2 = arr[n - 1 - i];
        int sum = value1 + value2;
        if (sum % k != 0) {
            return false;
        }
        int count1 = count.get(value1);
        int count2 = count.get(value2);
        if (count1 < 2 || count2 < 2) {
            return false;
        }
        count.put(value1, count1 - 2);
        count.put(value2, count2 - 2);
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) {
        return false;
    }
    int[] pairs = new int[n / 2];
    for (int i = 0; i < n; i += 2) {
        if (arr[i] + arr[i + 1] % k != 0) {
            return false;
        }
        pairs[i / 2] = arr[i] + arr[i + 1];
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) return false;
    int[] sum = new int[n/2];
    for (int i = 0; i < n/2; i++) {
        sum[i] = arr[2*i] + arr[2*i+1];
    }
    for (int i = 0; i < n/2; i++) {
        if (sum[i] % k != 0) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Check if the length of the array is even
    if (arr.length % 2 != 0) return false;

    // Sort the array in ascending order
    Arrays.sort(arr);

    // Initialize the sum of each pair to 0
    int sum = 0;

    // Loop through the array in pairs
    for (int i = 0; i < arr.length; i += 2) {
        // Check if the sum of the pair is divisible by k
        if (sum % k == 0) return true;

        // Add the sum of the current pair to the total sum
        sum += arr[i] + arr[i + 1];
    }

    // If the sum is divisible by k, return true
    return sum % k == 0;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 1) {
        return false;
    }
    int[] counts = new int[k];
    for (int i = 0; i < arr.length; i++) {
        int index = arr[i] % k;
        if (counts[index] == 1) {
            return false;
        }
        counts[index]++;
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] time = new int[n];
    Arrays.fill(time, Integer.MAX_VALUE);
    time[0] = 0;

    // BFS to calculate the minimum time to reach each node
    for (int i = 0; i < n; i++) {
        for (int[] edge : edges) {
            int from = edge[0], to = edge[1];
            time[to] = Math.min(time[to], time[from] + 1);
        }
    }

    // Calculate the total time required to collect the apples
    int totalTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            totalTime += time[i];
        }
    }

    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distance = new int[n];
    boolean[] visited = new boolean[n];

    distance[0] = 0;
    visited[0] = true;

    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < edges.length; j++) {
            int from = edges[j][0];
            int to = edges[j][1];
            if (!visited[from]) {
                distance[from] = distance[to] + 1;
                visited[from] = true;
            }
            if (!visited[to]) {
                distance[to] = distance[from] + 1;
                visited[to] = true;
            }
        }
    }

    int totalTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            totalTime += distance[i];
        }
    }

    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    dist[0] = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < edges.length; j++) {
            int u = edges[j][0], v = edges[j][1];
            if (dist[u] != Integer.MAX_VALUE && dist[v] > dist[u] + 1) {
                dist[v] = dist[u] + 1;
            }
        }
    }
    int minTime = Integer.MAX_VALUE;
    for (int i = 1; i < n; i++) {
        if (dist[i] < minTime && hasApple[i]) {
            minTime = dist[i];
        }
    }
    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distance = new int[n];
    int[] prev = new int[n];

    // Initialize the distance of node 0 to 0 and the previous node to -1
    distance[0] = 0;
    prev[0] = -1;

    // Loop through each node
    for (int node = 0; node < n; node++) {
        // Loop through each edge
        for (int i = 0; i < edges.length; i++) {
            int from = edges[i][0];
            int to = edges[i][1];

            // If the to node has an apple and the distance from the start node to the to node is less than the current minimum distance
            if (hasApple[to] && distance[from] + 1 < distance[to]) {
                // Update the distance and previous node
                distance[to] = distance[from] + 1;
                prev[to] = from;
            }
        }
    }

    // Initialize the total time to 0
    int totalTime = 0;

    // Loop through each node
    for (int node = 0; node < n; node++) {
        // If the node has an apple, add the distance to the total time
        if (hasApple[node]) {
            totalTime += distance[node];
        }
    }

    // Return the total time
    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the distance array with -1
    int[] distances = new int[n];
    Arrays.fill(distances, -1);

    // Initialize the visited array with false
    boolean[] visited = new boolean[n];
    Arrays.fill(visited, false);

    // Initialize the time variable with 0
    int time = 0;

    // Start from node 0 and calculate the minimum time to collect all the apples and return to node 0
    minTime(n, edges, hasApple, 0, visited, distances, time);

    // Return the final time
    return time;
}

private void minTime(int n, int[][] edges, boolean[] hasApple, int node, boolean[] visited, int[] distances, int time) {
    // If the current node has not been visited before, mark it as visited
    if (!visited[node]) {
        visited[node] = true;
    }

    // If the current node has an apple, increase the time by 1
    if (hasApple[node]) {
        time++;
    }

    // Get the distance of the current node
    int distance = distances[node];

    // If the distance has not been calculated before or the current distance is lower, update the distance
    if (distance == -1 || distance > time) {
        distances[node] = time;
    }

    // Iterate over the neighbors
    for (int neighbor : edges[node]) {
        // If the neighbor has not been visited before, recursively call the function
        if (!visited[neighbor]) {
            minTime(n, edges, hasApple, neighbor, visited, distances, time);
        }
    }
}

public String sortString(String s) {
    List<Character> characters = new ArrayList<>();
    for (char c : s.toCharArray()) {
        characters.add(c);
    }
    // Sort the characters in ascending order
    Collections.sort(characters);
    StringBuilder result = new StringBuilder();
    // Step 1: Add smallest character
    result.append(characters.get(0));
    // Step 2: Add smallest character that is greater than the last appended character
    for (int i = 1; i < characters.size(); i++) {
        if (characters.get(i) > result.charAt(result.length() - 1)) {
            result.append(characters.get(i));
        }
    }
    // Step 3: Add largest character
    result.append(characters.get(characters.size() - 1));
    // Step 4: Add largest character that is smaller than the last appended character
    for (int i = characters.size() - 2; i >= 0; i--) {
        if (characters.get(i) < result.charAt(result.length() - 1)) {
            result.append(characters.get(i));
        }
    }
    return result.toString();
}

