public String sortString(String s) {
    // Step 1: Pick the smallest character from s and append it to the result.
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == result.charAt(0)) {
            continue;
        }
        result.append(c);
    }

    // Step 2: Pick the smallest character from s which is greater than the last appended character to the result and append it.
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c < result.charAt(0) || c == result.charAt(0)) {
            continue;
        }
        result.append(c);
    }

    // Step 3: Repeat step 2 until you cannot pick more characters.
    while (result.length() < s.length()) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < result.charAt(0) || c == result.charAt(0)) {
                continue;
            }
            result.append(c);
        }
    }

    // Step 4: Pick the largest character from s and append it to the result.
    for (int i = s.length() - 1; i >= 0; i--) {
        char c = s.charAt(i);
        if (c == result.charAt(result.length() - 1)) {
            continue;
        }
        result.append(c);
    }

    // Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it.
    for (int i = s.length() - 1; i >= 0; i--) {
        char c = s.charAt(i);
        if (c > result.charAt(result.length() - 1)) {
            continue;
        }
        result.append(c);
    }

    // Step 6: Repeat step 5 until you cannot pick more characters.
    while (result.length() < s.length()) {
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c > result.charAt(result.length() - 1)) {
                continue;
            }
            result.append(c);
        }
    }

    return result.toString();
}

public String sortString(String s) {
    StringBuilder sb = new StringBuilder();

    // Step 1: Get smallest character from s
    Character smallest = getSmallestChar(s);
    sb.append(smallest);

    // Step 2: Get smallest character from s that is greater than the last appended character
    Character nextSmallest = getNextSmallestChar(s, smallest);
    while (nextSmallest != null) {
        sb.append(nextSmallest);
        nextSmallest = getNextSmallestChar(s, nextSmallest);
    }

    // Step 3: Get largest character from s
    Character largest = getLargestChar(s);
    sb.append(largest);

    // Step 4: Get largest character from s that is smaller than the last appended character
    Character nextLargest = getNextLargestChar(s, largest);
    while (nextLargest != null) {
        sb.append(nextLargest);
        nextLargest = getNextLargestChar(s, nextLargest);
    }

    // Step 5: Repeat steps 1-4 until all characters are added
    while (sb.length() < s.length()) {
        smallest = getSmallestChar(s);
        sb.append(smallest);
        nextSmallest = getNextSmallestChar(s, smallest);
        while (nextSmallest != null) {
            sb.append(nextSmallest);
            nextSmallest = getNextSmallestChar(s, nextSmallest);
        }
        largest = getLargestChar(s);
        sb.append(largest);
        nextLargest = getNextLargestChar(s, largest);
        while (nextLargest != null) {
            sb.append(nextLargest);
            nextLargest = getNextLargestChar(s, nextLargest);
        }
    }

    return sb.toString();
}

private Character getSmallestChar(String s) {
    Character smallest = null;
    for (int i = 0; i < s.length(); i++) {
        Character c = s.charAt(i);
        if (smallest == null || smallest.compareTo(c) > 0) {
            smallest = c;
        }
    }
    return smallest;
}

private Character getNextSmallestChar(String s, Character currentSmallest) {
    Character nextSmallest = null;
    for (int i = 0; i < s.length(); i++) {
        Character c = s.charAt(i);
        if (c.compareTo(currentSmallest) > 0 && (nextSmallest == null || nextSmallest.compareTo(c) > 0)) {
            nextSmallest = c;
        }
    }
    return nextSmallest;
}

private Character getLargestChar(String s) {
    Character largest = null;
    for (int i = 0; i < s.length(); i++) {
        Character c = s.charAt(i);
        if (largest == null || largest.compareTo(c) < 0) {
            largest = c;
        }
    }
    return largest;
}

private Character getNextLargestChar(String s, Character currentLargest) {
    Character nextLargest = null;
    for (int i = 0; i < s.length(); i++) {
        Character c = s.charAt(i);
        if (c.compareTo(currentLargest) < 0 && (nextLargest == null || nextLargest.compareTo(c) < 0)) {
            nextLargest = c;
        }
    }
    return nextLargest;
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder result = new StringBuilder();
    int i = 0;

    while (i < chars.length) {
        char current = chars[i];
        char smallest = current;
        char largest = current;
        int smallestIndex = i;
        int largestIndex = i;
        int j = i + 1;

        while (j < chars.length) {
            if (chars[j] < smallest) {
                smallest = chars[j];
                smallestIndex = j;
            } else if (chars[j] > largest) {
                largest = chars[j];
                largestIndex = j;
            }
            j++;
        }

        if (smallest == current) {
            // smallest character is the current character
            result.append(smallest);
            i = smallestIndex;
        } else {
            // move to next character whose index is larger than the current character's index
            // this ensures that the smallest character is picked only once
            int nextIndex = smallestIndex + 1;
            while (nextIndex < chars.length && chars[nextIndex] == smallest) {
                nextIndex++;
            }
            if (nextIndex < chars.length) {
                i = nextIndex;
                result.append(smallest);
            }
        }

        if (largest == current) {
            // largest character is the current character
            result.append(largest);
            i = largestIndex;
        } else {
            // move to next character whose index is smaller than the current character's index
            // this ensures that the largest character is picked only once
            int nextIndex = largestIndex - 1;
            while (nextIndex >= 0 && chars[nextIndex] == largest) {
                nextIndex--;
            }
            if (nextIndex >= 0) {
                i = nextIndex;
                result.append(largest);
            }
        }
    }

    return result.toString();
}

