public int minCostClimbingStairs(int[] cost){
  // Special case: if the array has only one element,
  // return the element as the minimum cost.
  if (cost.length == 1) {
    return cost[0];
  }
  // Initialize two variables to store the minimum cost of
  // climbing the stairs.
  var cost1 = 0;
  var cost2 = 0;
  // Iterate through the array.
  for (var i = 0; i < cost.length; i++) {
    // Calculate the cost of climbing the stairs from the current step.
    cost1 = Math.min(cost1, cost2) + cost[i];
    // Update the cost2 variable.
    cost2 = cost1 - cost[i];
  }
  // Return the minimum cost.
  return Math.min(cost1, cost2);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int dp0 = cost[0];
    int dp1 = cost[1];
    for (int i = 2; i < n; i++) {
        int prev0 = dp0;
        int prev1 = dp1;
        dp0 = Math.min(prev0, prev1) + cost[i];
        dp1 = Math.min(prev0, prev1) + cost[i];
    }
    return Math.min(dp0, dp1);
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = cost[0];
    int currentCost = 0;
    for (int i = 2; i < cost.length; i++) {
        currentCost = Math.min(minCost, cost[i-1]) + cost[i];
        minCost = currentCost;
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost.length == 0) {
        return 0;
    } else if (cost.length == 1) {
        return cost[0];
    } else if (cost.length == 2) {
        return Math.min(cost[0], cost[1]);
    }

    int first = cost[0];
    int second = cost[1];
    int third = cost[2];

    for (int i = 3; i < cost.length; i++) {
        first = Math.min(first + cost[i], second + cost[i - 1]);
        second = Math.min(second + cost[i - 1], third + cost[i - 2]);
        third = Math.min(third + cost[i - 2], second + cost[i]);
    }

    return Math.min(first, Math.min(second, third));
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    } else if (cost.length == 1) {
        return cost[0];
    } else if (cost.length == 2) {
        return Math.min(cost[0], cost[1]);
    }

    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i], dp[i - 2] + cost[i - 1]);
    }

    return dp[cost.length - 1];
}

