        transformations.add(morseCode);
    }

    // Return the size of the set
    return transformations.size();
}

private String convertWordToMorseCode(String word) {
    // Initialize an empty string to store the Morse code
    String morseCode = "";

    // Iterate through each letter in the word
    for (char letter : word.toCharArray()) {
        // Get the corresponding Morse code for the current letter
        String morseLetter = getMorseLetter(letter);

        // Add the Morse letter to the Morse code string
        morseCode += morseLetter;
    }

    // Return the complete Morse code
    return morseCode;
}

private String getMorseLetter(char letter) {
    // Create a map of Morse codes for each letter
    Map<Character, String> morseCodes = new HashMap<>();
    morseCodes.put('a', ".-");
    morseCodes.put('b', "-...");
    morseCodes.put('c', "-.-.");
    // ...

    // Return the Morse code for the current letter
    return morseCodes.get(letter);
}

