public static boolean hasAllCodes(String s, int k) {
    int n = s.length();
    for (int i = 0; i < n - k + 1; i++) {
        String subStr = s.substring(i, i + k);
        if (!subStr.matches("^[01]{" + k + "}$")) {
            return false;
        }
    }
    return true;
}

