    return true;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int windowStart = 0;
    int windowEnd = k - 1;
    boolean foundCode = false;

    while (windowEnd < n) {
        String window = s.substring(windowStart, windowEnd + 1);
        foundCode = false;

        for (int i = windowStart; i <= windowEnd; i++) {
            String code = s.substring(i, i + k);

            if (window.equals(code)) {
                foundCode = true;
                break;
            }
        }

        if (!foundCode) {
            return false;
        }

        windowStart++;
        windowEnd++;
    }

    return true;
}

