public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minOperations = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[i] != arr[j]) {
                minOperations++;
                arr[i]--;
                arr[j]++;
            }
        }
    }
    return minOperations;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int operations = 0;
    for (int i = 0; i < n; i++) {
        while (arr[i] != arr[i - 1]) {
            operations++;
            int index1 = i;
            int index2 = i - 1;
            arr[index1] -= 1;
            arr[index2] += 1;
        }
    }
    return operations;
}

public int minOperations(int n) {
    int arr[] = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = 2 * i + 1;
    }
    int minOperations = 0;
    for (int i = 0; i < n; i++) {
        int diff = arr[i] - 1;
        for (int j = 0; j < n; j++) {
            if (arr[i] > arr[j] && diff > 0) {
                arr[j] += 1;
                arr[i] -= 1;
                minOperations++;
                diff--;
            }
        }
    }
    return minOperations;
}

public int minOperations(int n) {
    int result = 0;
    // Loop through each element in the array
    for (int i = 0; i < n; i++) {
        // Calculate the difference between the element and the target value (which is (2 * i) + 1)
        int difference = arr[i] - ((2 * i) + 1);
        // If the difference is odd, add 1 to the result and swap the element with the next element
        if (difference % 2 == 1) {
            result++;
            int temp = arr[i];
            arr[i] = arr[i + 1];
            arr[i + 1] = temp;
        }
    }
    return result;
}

