        if (k == nextFibonacciNumber) {
            return minFibonacciNumbers + 1;
        } else if (k < nextFibonacciNumber) {
            return minFibonacciNumbers;
        } else {
            minFibonacciNumbers++;
            prevFibonacciNumber = currFibonacciNumber;
            currFibonacciNumber = nextFibonacciNumber;
        }
    }
    return minFibonacciNumbers;
}

