public int findMinFibonacciNumbers(int k) {
    if (k == 0) return 0;
    if (k == 1) return 1;
    int[] fib = {1, 1};
    int i = 2;
    while (fib[i - 1] + fib[i - 2] <= k) {
        fib[i] = fib[i - 1] + fib[i - 2];
        i++;
    }
    int min = Floor((k - fib[i - 1]) / fib[i - 2]);
    for (int j = i - 1; j >= 0; j--) {
        if (min >= fib[j]) {
            min -= fib[j];
        } else {
            min = Floor((k - fib[j]) / fib[j - 1]);
        }
    }
    return min + 1;
}

public int findMinFibonacciNumbers(int k) {
    int[] fib = {1, 1};
    int i = 2;
    while (fib[i - 1] < k) {
        fib[i] = fib[i - 1] + fib[i - 2];
        i++;
    }
    int min = Integer.MAX_VALUE;
    for (int j = 0; j < i; j++) {
        min = Math.min(min, fib[j] + findMinFibonacciNumbers(k - fib[j]));
    }
    return min;
}

