                maxLength = Math.max(maxLength, countHorizontal(mat, i, j));

                // Check the vertical length
                maxLength = Math.max(maxLength, countVertical(mat, i, j));

                // Check the diagonal length
                maxLength = Math.max(maxLength, countDiagonal(mat, i, j));

                // Check the anti-diagonal length
                maxLength = Math.max(maxLength, countAntidiagonal(mat, i, j));
            }
        }
    }

    // Return the maximum length
    return maxLength;
}

private static int countHorizontal(int[][] mat, int row, int col) {
    int length = 0;
    for (int i = col; i < mat[row].length && mat[row][i] == 1; i++) {
        length++;
    }
    return length;
}

private static int countVertical(int[][] mat, int row, int col) {
    int length = 0;
    for (int i = row; i < mat.length && mat[i][col] == 1; i++) {
        length++;
    }
    return length;
}

private static int countDiagonal(int[][] mat, int row, int col) {
    int length = 0;
    for (int i = row, j = col; i < mat.length && j < mat[i].length && mat[i][j] == 1; i++, j++) {
        length++;
    }
    return length;
}

private static int countAntidiagonal(int[][] mat, int row, int col) {
    int length = 0;
    for (int i = row, j = col; i < mat.length && j >= 0 && mat[i][j] == 1; i++, j--) {
        length++;
    }
    return length;
}

