private static int squarePermutations(int[] A, int i, int sum, int[][] dp) {
    if (i == A.length) {
        return sum == 0 ? 1 : 0;
    }
    if (dp[i][sum] != -1) {
        return dp[i][sum];
    }
    int count = 0;
    for (int j = 0; j < A.length; j++) {
        if (i != j && Math.sqrt(sum + A[i] * A[j]) % 1 == 0) {
            count += squarePermutations(A, i + 1, sum + A[i] * A[j], dp);
        }
    }
    return dp[i][sum] = count;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    for (int i = 0; i < heights.length; i++) {
        int area = heights[i];
        for (int j = i + 1; j < heights.length; j++) {
            area = Math.max(area, heights[j] * (j - i + 1));
        }
        maxArea = Math.max(maxArea, area);
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int maxArea = 0;
    for (int i = 1; i < n; i++) {
        int pos = i - 1;
        while (pos >= 0 && heights[pos] >= heights[i]) {
            pos = left[pos];
        }
        left[i] = pos;
    }
    for (int i = n - 2; i >= 0; i--) {
        int pos = i + 1;
        while (pos < n && heights[pos] >= heights[i]) {
            pos = right[pos];
        }
        right[i] = pos;
    }
    for (int i = 0; i < n; i++) {
        int area = heights[i] * (right[i] - left[i] - 1);
        maxArea = Math.max(maxArea, area);
    }
    return maxArea;
}

