public static int[] diagonalOrder(int[][] mat) {
    // Initialize the output array with the correct length
    int[] output = new int[mat.length * mat[0].length];
    // Initialize indices for the current row and column
    int row = 0, col = 0;
    // Loop through each element in the matrix
    for (int i = 0; i < mat.length; i++) {
        // For each row, loop through the elements in that row
        for (int j = 0; j < mat[i].length; j++) {
            // If we're still within the bounds of the matrix, add the element to the output array
            if (row < mat.length && col < mat[0].length) {
                output[i] = mat[row][col];
            }
            // Increment the column index for the next element
            col++;
            // If we're at the end of a row, increment the row index and reset the column index
            if (col == mat[0].length) {
                row++;
                col = 0;
            }
        }
        // Increment the row index for the next row
        row++;
    }
    // Return the output array
    return output;
}

