    int k = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[i].length - 1; j++) {
            if (i + j == mat.length - 1) {
                result[k++] = mat[i][j];
            } else if (i + j < mat.length - 1) {
                result[k++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int numRows = mat.length;
    int numCols = mat[0].length;
    int[][] diagonalElements = new int[numRows][numCols];
    int currentRow = 0;
    int currentCol = 0;
    int direction = 1;
    for (int i = 0; i < numRows; i++) {
        diagonalElements[i][0] = mat[currentRow][currentCol];
        currentRow += direction;
        currentCol += direction;
        if (currentRow == numRows || currentCol == numCols) {
            currentRow = numRows - 1;
            currentCol = numCols - 1;
            direction *= -1;
        }
    }
    int[] result = new int[numRows * numCols];
    int index = 0;
    for (int[] row : diagonalElements) {
        for (int element : row) {
            result[index++] = element;
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    String numStr = Integer.toString(n);
    ArrayList<Integer> digits = new ArrayList<>();
    for (int i = 0; i < numStr.length(); i++) {
        digits.add(Integer.parseInt(numStr.substring(i, i + 1)));
    }
    Collections.sort(digits);
    Integer smallestNum = 0;
    for (int i = 0; i < digits.size() - 1; i++) {
        smallestNum += digits.get(i) * Math.pow(10, digits.size() - i - 1);
    }
    smallestNum = smallestNum + digits.get(digits.size() - 1);
    return smallestNum;
}

