    }
}

public static int findSmallestInteger(int n) {
    // Split the input integer into individual digits
    String[] digits = String.valueOf(n).split("");

    // Sort the digits in ascending order
    Arrays.sort(digits);

    // Concatenate the digits back into a string
    String sortedDigits = String.join("", digits);

    // Convert the sorted digits string back into an integer
    int smallestInteger = Integer.parseInt(sortedDigits);

    // Check if the smallest integer is greater than the input integer
    if (smallestInteger > n) {
        return smallestInteger;
    } else {
        return -1;
    }
}

public static int findSmallestInteger(int n) {
    if (n <= 9) return -1;
    int[] digits = new int[10];
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
    }
    int min = -1;
    for (int i = 9; i >= 0; i--) {
        if (digits[i] > 0 && (min == -1 || min > i)) {
            min = i;
        }
    }
    return min > 0 ? min * 10 + findSmallestInteger(min) : -1;
}

public static int findSmallestInteger(int n) {
    // sort the digits in ascending order
    String nStr = String.valueOf(n);
    char[] nChars = nStr.toCharArray();
    Arrays.sort(nChars);

    // rearrange the digits to form the smallest integer
    int smallest = 0;
    for (char c : nChars) {
        smallest = smallest * 10 + c - '0';
    }

    // check if the smallest integer is greater than n
    if (smallest > n) {
        return smallest;
    } else {
        return -1;
    }
}

