}

public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    for (int i = 1; i < n; i++) {
        int n2 = uglyNumbers[i2] * 2;
        int n3 = uglyNumbers[i3] * 3;
        int n5 = uglyNumbers[i5] * 5;
        uglyNumbers[i] = Math.min(n2, Math.min(n3, n5));

        if (uglyNumbers[i] == n2) i2++;
        if (uglyNumbers[i] == n3) i3++;
        if (uglyNumbers[i] == n5) i5++;
    }

    return uglyNumbers[n - 1];
}

