    int i2 = 0, i3 = 0, i5 = 0;

    for (int i = 1; i < n; i++) {
        int min = Math.min(uglyNumbers[i2] * 2, Math.min(uglyNumbers[i3] * 3, uglyNumbers[i5] * 5));
        uglyNumbers[i] = min;

        if (min == uglyNumbers[i2] * 2) {
            i2++;
        }

        if (min == uglyNumbers[i3] * 3) {
            i3++;
        }

        if (min == uglyNumbers[i5] * 5) {
            i5++;
        }
    }

    return uglyNumbers[n - 1];
}

public static int findNthUglyNumber(int n) {
    // Initialize an array to store the ugly numbers
    int[] uglyNums = new int[n];
    // Initialize an index to track the current ugly number being processed
    int i = 0;
    // Initialize variables to track the current values of the three multiples
    int mul2 = 0, mul3 = 0, mul5 = 0;

    // Initialize the first three ugly numbers
    uglyNums[0] = 1;
    uglyNums[1] = 2;
    uglyNums[2] = 3;

    // Iterate through the remaining ugly numbers
    for (i = 3; i < n; i++) {
        // Find the minimum of the three current multiples
        int min = Math.min(uglyNums[mul2] * 2, Math.min(uglyNums[mul3] * 3, uglyNums[mul5] * 5));
        // Add the minimum to the array and increment the corresponding multiple index
        uglyNums[i] = min;
        if (min == uglyNums[mul2] * 2) mul2++;
        if (min == uglyNums[mul3] * 3) mul3++;
        if (min == uglyNums[mul5] * 5) mul5++;
    }

    // Return the last ugly number in the array
    return uglyNums[n - 1];
}

