        } else {
            maxEnergy = Math.max(maxEnergy, energy);
            energy = 1;
            currChar = s.charAt(i);
        }
    }
    maxEnergy = Math.max(maxEnergy, energy);
    return maxEnergy;
}

public static int calculateEnergy(String s) {
  int maxEnergy = 0;
  int currentLength = 0;
  char currentChar = s.charAt(0);

  for (int i = 1; i < s.length(); i++) {
    if (s.charAt(i) == currentChar) {
      currentLength++;
    } else {
      if (currentLength > maxEnergy) {
        maxEnergy = currentLength;
      }
      currentChar = s.charAt(i);
      currentLength = 1;
    }
  }

  if (currentLength > maxEnergy) {
    maxEnergy = currentLength;
  }

  return maxEnergy;
}

public static int calculateEnergy(String s) {

  // Initialize variables
  int energy = 0;
  int length = s.length();
  int start = 0;
  int end = 0;

  // Iterate through the string character by character
  for (int i = 0; i < length; i++) {

    // Determine the length of the current substring
    start = i;
    while (i < length && s.charAt(i) == s.charAt(start)) {
      i++;
    }
    end = i - 1;

    // Update the energy if the current substring is longer than the previous one
    if (end - start + 1 > energy) {
      energy = end - start + 1;
    }
  }

  return energy;
}

