    int maxEnergy = 0;
    char[] chars = s.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        char c = chars[i];
        int j;
        for (j = i + 1; j < chars.length && chars[j] == c; j++) {
            energy++;
        }
        if (energy > maxEnergy) {
            maxEnergy = energy;
        }
        energy = 0;
        i = j - 1;
    }
    return maxEnergy;
}

