public static int calculateUniqueSum(int[] nums) {
    Set<Integer> unique = new HashSet<>();
    for (int num : nums) {
        unique.add(num);
    }
    int sum = 0;
    for (int num : unique) {
        sum += num;
    }
    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    HashSet<Integer> seen = new HashSet<>();
    for (int num : nums) {
