public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        count++;
        n -= i * i;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    int[] squares = new int[n];

    for (int i = 1; i * i <= n; i++) {
        squares[i] = i * i;
    }

    for (int i = n; i > 0; i--) {
        if (squares[i] > n) {
            continue;
        }
        count++;
        n -= squares[i];
    }

    return count;
}

public static int minPerfectSquareSum(int n) {
    int result = 0;
    int i = 1;
    while (i * i <= n) {
        int count = 1;
        while (i * i * count <= n) {
            count++;
        }
        result += count - 1;
        i++;
    }
    return result;
}

public static int minPerfectSquareSum(int n) {
    int result = 0;
    for (int i = 1; i * i <= n; i++) {
        result += n / (i * i);
    }
    return result;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int square = (int) Math.sqrt(n);
        count++;
        n -= square;
    }
    return count;
}

